import { useState } from "react";
import { Link, useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Mail, Lock, User as UserIcon, ArrowLeft, GraduationCap, CircleCheck as CheckCircle2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/selection-controls";
import { useAuth } from "@/contexts/auth-context";
import { useToast } from "@/contexts/toast-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

type AuthMode = "login" | "register" | "forgot";

export function AuthPage({ mode }: { mode: AuthMode }) {
  const navigate = useNavigate();
  const { login, register, forgotPassword } = useAuth();
  const { showToast } = useToast();
  const reduced = usePrefersReducedMotion();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [emailSent, setEmailSent] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    setIsLoading(true);

    try {
      if (mode === "login") {
        await login(email, password, rememberMe);
        showToast("Welcome back!", "success");
        navigate("/home");
      } else if (mode === "register") {
        if (!fullName.trim()) throw new Error("Please enter your full name.");
        await register(email, password, fullName, rememberMe);
        showToast("Account created! Check your email for verification.", "success");
        navigate("/home");
      } else {
        await forgotPassword(email);
        setEmailSent(true);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setIsLoading(false);
    }
  }

  const titles = {
    login: { eyebrow: "Welcome back", title: "Sign in to PayPlate", desc: "Your campus food wallet is waiting." },
    register: { eyebrow: "Join PayPlate", title: "Create your account", desc: "Student-exclusive deals, wallet, and rewards." },
    forgot: { eyebrow: "Reset password", title: "Forgot your password?", desc: "We'll send you a reset link." },
  };

  const t = titles[mode];

  return (
    <div className="grid min-h-screen lg:grid-cols-2">
      {/* Left visual panel */}
      <div className="relative hidden overflow-hidden bg-gradient-to-br from-primary via-primary-600 to-dark lg:block">
        <div className="absolute inset-0">
          <div className="absolute -left-20 top-20 size-72 rounded-full bg-white/10 blur-3xl" />
          <div className="absolute -right-20 bottom-20 size-72 rounded-full bg-white/5 blur-3xl" />
          <motion.div
            animate={reduced ? undefined : { y: [0, -20, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
            className="absolute left-1/2 top-1/3 -translate-x-1/2"
          >
            <div className="rounded-3xl bg-white/15 p-8 backdrop-blur-md">
              <GraduationCap size={48} className="text-white" />
            </div>
          </motion.div>
        </div>
        <div className="relative flex h-full flex-col justify-end p-12">
          <h2 className="font-heading text-4xl font-black text-white">Campus food, simplified.</h2>
          <p className="mt-3 max-w-md text-white/80">
            Order from your favourite campus restaurants, pay with your wallet, and earn rewards on every purchase.
          </p>
        </div>
      </div>

      {/* Right form panel */}
      <div className="flex items-center justify-center p-6 lg:p-12">
        <div className="w-full max-w-sm">
          <Link to="/" className="mb-8 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-text">
            <ArrowLeft size={16} /> Back home
          </Link>

          <p className="text-sm font-bold text-primary">{t.eyebrow}</p>
          <h1 className="mt-1 font-heading text-3xl font-black">{t.title}</h1>
          <p className="mt-2 text-sm text-muted-foreground">{t.desc}</p>

          {mode === "forgot" && emailSent ? (
            <div className="mt-8 rounded-2xl border border-border bg-card p-6 text-center">
              <CheckCircle2 size={40} className="mx-auto text-success" />
              <h3 className="mt-4 font-heading text-lg font-black">Check your inbox</h3>
              <p className="mt-2 text-sm text-muted-foreground">
                If an account exists for {email}, we've sent a password reset link.
              </p>
              <Link to="/login">
                <Button variant="secondary" className="mt-6 w-full">Back to sign in</Button>
              </Link>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="mt-8 space-y-4">
              {mode === "register" && (
                <Input
                  label="Full name"
                  name="fullName"
                  placeholder="Jane Doe"
                  icon={<UserIcon size={18} />}
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  required
                />
              )}

              <Input
                label="Email"
                name="email"
                type="email"
                placeholder="jane@university.ac.za"
                icon={<Mail size={18} />}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />

              {mode !== "forgot" && (
                <Input
                  label="Password"
                  name="password"
                  type="password"
                  placeholder="••••••••"
                  icon={<Lock size={18} />}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              )}

              {mode === "login" && (
                <div className="flex items-center justify-between">
                  <Checkbox checked={rememberMe} onChange={setRememberMe} label="Remember me" />
                  <Link to="/forgot-password" className="text-sm font-bold text-primary hover:underline">
                    Forgot password?
                  </Link>
                </div>
              )}

              {error && (
                <div className="rounded-xl bg-danger/10 px-4 py-3 text-sm font-bold text-danger">
                  {error}
                </div>
              )}

              <Button type="submit" disabled={isLoading} className="w-full">
                {isLoading ? "Please wait…" : mode === "login" ? "Sign in" : mode === "register" ? "Create account" : "Send reset link"}
              </Button>
            </form>
          )}

          {mode === "login" && (
            <p className="mt-6 text-center text-sm text-muted-foreground">
              Don't have an account?{" "}
              <Link to="/register" className="font-bold text-primary hover:underline">Sign up</Link>
            </p>
          )}
          {mode === "register" && (
            <p className="mt-6 text-center text-sm text-muted-foreground">
              Already have an account?{" "}
              <Link to="/login" className="font-bold text-primary hover:underline">Sign in</Link>
            </p>
          )}
          {mode === "forgot" && !emailSent && (
            <p className="mt-6 text-center text-sm text-muted-foreground">
              Remembered it?{" "}
              <Link to="/login" className="font-bold text-primary hover:underline">Back to sign in</Link>
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

import { useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Plus, Minus, Trash2, ShoppingBag, ArrowRight, Tag, GraduationCap } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { EmptyState } from "@/components/ui/empty-state";
import { useCart } from "@/contexts/cart-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { formatRand } from "@/services/payplate-data";
import { useState } from "react";

export function CartPage() {
  const navigate = useNavigate();
  const { items, updateQuantity, removeItem, subtotalCents, studentDiscountCents, deliveryFeeCents, totalCents, itemCount } = useCart();
  const reduced = usePrefersReducedMotion();
  const [promoCode, setPromoCode] = useState("");
  const [promoApplied, setPromoApplied] = useState(false);
  const [promoError, setPromoError] = useState("");

  function applyPromo() {
    if (!promoCode.trim()) return;
    if (promoCode.toUpperCase() === "STUDENT10") {
      setPromoApplied(true);
      setPromoError("");
    } else {
      setPromoError("Invalid promo code. Try STUDENT10.");
      setPromoApplied(false);
    }
  }

  if (items.length === 0) {
    return (
      <AppShell>
        <EmptyState
          icon={<ShoppingBag size={32} />}
          title="Your cart is empty"
          description="Browse restaurants and add meals to get started."
          action={<Button onClick={() => navigate("/restaurants")}>Browse restaurants</Button>}
        />
      </AppShell>
    );
  }

  const promoDiscount = promoApplied ? Math.round(subtotalCents * 0.1) : 0;
  const finalTotal = totalCents - promoDiscount;

  return (
    <AppShell>
      <div className="space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Your cart</h1>
          <p className="mt-1 text-sm text-muted-foreground">{itemCount} item{itemCount > 1 ? "s" : ""}</p>
        </div>

        <div className="grid gap-6 lg:grid-cols-3">
          {/* Items */}
          <div className="space-y-3 lg:col-span-2">
            {items.map((ci, i) => (
              <motion.div
                key={ci.item.id}
                initial={reduced ? undefined : { opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ delay: i * 0.05 }}
              >
                <Card className="grid grid-cols-[80px_1fr_auto] items-center gap-4 p-3">
                  <img src={ci.item.image} alt={ci.item.name} className="aspect-square w-full rounded-xl object-cover" />
                  <div className="min-w-0">
                    <h3 className="truncate font-heading font-black">{ci.item.name}</h3>
                    <p className="text-sm text-muted-foreground">{formatRand(ci.item.priceCents)} each</p>
                    <div className="mt-2 flex items-center gap-2">
                      <button
                        onClick={() => updateQuantity(ci.item.id, ci.quantity - 1)}
                        className="grid size-8 place-items-center rounded-lg bg-muted"
                        aria-label="Decrease"
                      >
                        <Minus size={14} />
                      </button>
                      <span className="min-w-6 text-center font-heading font-black tabular-nums">{ci.quantity}</span>
                      <button
                        onClick={() => updateQuantity(ci.item.id, ci.quantity + 1)}
                        className="grid size-8 place-items-center rounded-lg bg-primary text-white"
                        aria-label="Increase"
                      >
                        <Plus size={14} />
                      </button>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <p className="font-heading font-black tabular-nums">{formatRand(ci.item.priceCents * ci.quantity)}</p>
                    <button
                      onClick={() => removeItem(ci.item.id)}
                      className="grid size-8 place-items-center rounded-lg text-muted-foreground hover:bg-danger/10 hover:text-danger"
                      aria-label="Remove item"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </Card>
              </motion.div>
            ))}
          </div>

          {/* Summary */}
          <div className="space-y-4">
            <Card>
              <h3 className="font-heading text-lg font-black">Order summary</h3>

              {/* Promo code */}
              <div className="mt-4">
                <div className="flex gap-2">
                  <Input
                    placeholder="Promo code"
                    value={promoCode}
                    onChange={(e) => setPromoCode(e.target.value)}
                    icon={<Tag size={16} />}
                  />
                  <Button variant="secondary" onClick={applyPromo} className="whitespace-nowrap">Apply</Button>
                </div>
                {promoError && <p className="mt-2 text-xs font-bold text-danger">{promoError}</p>}
                {promoApplied && <p className="mt-2 text-xs font-bold text-success">10% promo applied!</p>}
              </div>

              <div className="mt-4 space-y-2 border-t border-border pt-4 text-sm">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Subtotal</span>
                  <span className="font-bold tabular-nums">{formatRand(subtotalCents)}</span>
                </div>
                <div className="flex justify-between text-success">
                  <span className="inline-flex items-center gap-1"><GraduationCap size={14} /> Student discount (15%)</span>
                  <span className="font-bold tabular-nums">−{formatRand(studentDiscountCents)}</span>
                </div>
                {promoApplied && (
                  <div className="flex justify-between text-success">
                    <span>Promo (STUDENT10)</span>
                    <span className="font-bold tabular-nums">−{formatRand(promoDiscount)}</span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Delivery fee</span>
                  <span className="font-bold tabular-nums">{formatRand(deliveryFeeCents)}</span>
                </div>
              </div>

              <div className="mt-4 flex items-center justify-between border-t border-border pt-4">
                <span className="font-heading text-lg font-black">Total</span>
                <motion.span
                  key={finalTotal}
                  initial={reduced ? undefined : { scale: 1.1 }}
                  animate={{ scale: 1 }}
                  className="font-heading text-2xl font-black text-primary tabular-nums"
                >
                  {formatRand(finalTotal)}
                </motion.span>
              </div>

              <Button className="mt-4 w-full" onClick={() => navigate("/checkout")}>
                Proceed to checkout <ArrowRight size={18} />
              </Button>
            </Card>

            <p className="text-center text-xs text-muted-foreground">
              You're saving {formatRand(studentDiscountCents + promoDiscount)} with student discounts
            </p>
          </div>
        </div>
      </div>
    </AppShell>
  );
}

import { useEffect, useState } from "react";
import { Link, useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import {
  Search, Bell, MapPin, Flame, ArrowRight, Star,
  ChevronRight, RotateCcw, Tag, Clock,
  Grid2x2, Sandwich, Pizza, CupSoda, Salad, Coffee, Fish,
} from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { RestaurantCard } from "@/components/domain/restaurant-card";
import { MenuItemCard } from "@/components/domain/menu-item-card";
import { useAuth } from "@/contexts/auth-context";
import { useWallet } from "@/contexts/wallet-context";
import { useRestaurants } from "@/contexts/restaurants-context";
import { useOrders } from "@/contexts/orders-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { allMenuItems, offers, recentlyOrderedItemIds, formatRand } from "@/services/payplate-data";
import type { Restaurant, MenuItem, Offer } from "@/types/payplate";

const CATEGORIES = [
  { icon: Grid2x2,  label: "All",     active: true  },
  { icon: Sandwich, label: "Burgers" },
  { icon: Pizza,    label: "Pizza"   },
  { icon: CupSoda,  label: "Drinks"  },
  { icon: Salad,    label: "Salads"  },
  { icon: Coffee,   label: "Coffee"  },
  { icon: Fish,     label: "Sushi"   },
];

export function Dashboard() {
  const { user } = useAuth();
  const { balanceCents, rewardPoints, tier } = useWallet();
  const { restaurants, isLoading } = useRestaurants();
  const { orders } = useOrders();
  const reduced = usePrefersReducedMotion();
  const navigate = useNavigate();

  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");
  const [popularMeals]  = useState<MenuItem[]>(allMenuItems.filter((m) => m.isPopular));
  const [recentlyOrdered] = useState<MenuItem[]>(
    recentlyOrderedItemIds
      .map((id) => allMenuItems.find((m) => m.id === id))
      .filter(Boolean) as MenuItem[],
  );
  const [nearby, setNearby] = useState<Restaurant[]>([]);
  const [studentOffers] = useState<Offer[]>(offers.filter((o) => o.isStudentExclusive));

  useEffect(() => {
    setNearby([...restaurants].sort((a, b) => parseFloat(a.distance) - parseFloat(b.distance)));
  }, [restaurants]);

  const firstName = user ? user.fullName.split(" ")[0] : "there";
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  const lastOrder = orders[0];

  function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    if (searchQuery.trim()) navigate(`/restaurants?q=${encodeURIComponent(searchQuery)}`);
  }

  return (
    <AppShell>
      <div className="space-y-5">
        {/* Header row */}
        <motion.div
          initial={reduced ? undefined : { opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-start justify-between gap-3"
        >
          <div>
            <button
              onClick={() => navigate("/restaurants")}
              className="inline-flex items-center gap-1 text-sm font-bold text-muted-foreground hover:text-primary transition-colors"
            >
              <MapPin size={14} className="text-primary" />
              University of Cape Town
              <ChevronRight size={14} />
            </button>
            <h1 className="mt-0.5 font-heading text-xl font-black">
              {greeting}, {firstName} 👋
            </h1>
          </div>
          <Link
            to="/notifications"
            className="relative grid size-10 shrink-0 place-items-center rounded-2xl bg-card ring-1 ring-border shadow-card"
          >
            <Bell size={18} />
            <span className="absolute right-2 top-2 size-2 rounded-full bg-primary" />
          </Link>
        </motion.div>

        {/* Search bar */}
        <motion.form
          onSubmit={handleSearch}
          initial={reduced ? undefined : { opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
        >
          <label className="flex items-center gap-2.5 rounded-2xl bg-card px-4 py-3 ring-1 ring-border shadow-card transition-shadow focus-within:ring-primary/40 focus-within:shadow-lift">
            <Search size={17} className="shrink-0 text-muted-foreground" />
            <input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search food, restaurants..."
              className="flex-1 bg-transparent text-sm font-medium text-text placeholder:text-muted-foreground outline-none"
            />
          </label>
        </motion.form>

        {/* Category chips */}
        <div className="scroll-snap-x">
          {CATEGORIES.map((cat) => (
            <button
              key={cat.label}
              onClick={() => setActiveCategory(cat.label)}
              className={`flex shrink-0 items-center gap-1.5 rounded-2xl px-4 py-2 text-sm font-black transition-all whitespace-nowrap ${
                activeCategory === cat.label
                  ? "bg-primary text-white shadow-lift"
                  : "bg-card text-muted-foreground ring-1 ring-border hover:text-text"
              }`}
            >
              <cat.icon size={15} strokeWidth={2.25} />
              {cat.label}
            </button>
          ))}
        </div>

        {/* Wallet mini-card */}
        <motion.div
          initial={reduced ? undefined : { opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.08 }}
          whileHover={!reduced ? { scale: 1.01 } : undefined}
        >
          <Link to="/wallet">
            <div
              className="relative overflow-hidden rounded-[1.75rem] p-5 text-white shadow-lift"
              style={{ background: "linear-gradient(135deg,#00D27A 0%,#008A50 60%,#050505 100%)" }}
            >
              <div className="pointer-events-none absolute -right-10 -top-10 size-40 rounded-full bg-white/10 blur-2xl" />
              <div className="pointer-events-none absolute -bottom-12 -left-6 size-36 rounded-full bg-accent/15 blur-2xl" />
              <div className="relative flex items-center justify-between">
                <div>
                  <p className="text-[11px] font-bold uppercase tracking-wide text-white/65">PayPlate Wallet</p>
                  <motion.p
                    key={balanceCents}
                    initial={reduced ? undefined : { opacity: 0, y: 6 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mt-1 font-heading text-3xl font-black tabular-nums"
                  >
                    {formatRand(balanceCents)}
                  </motion.p>
                  <p className="mt-0.5 text-[11px] text-white/60">Available Balance</p>
                  <div className="mt-2 inline-flex items-center gap-1.5 rounded-full bg-white/15 px-2.5 py-1 text-[11px] font-bold">
                    🏆 {rewardPoints} pts · <span className="capitalize">{tier}</span> tier
                  </div>
                </div>
                <div className="flex flex-col items-end gap-2">
                  <div className="grid size-12 place-items-center rounded-2xl bg-white/15 backdrop-blur-sm">
                    <ChevronRight size={22} />
                  </div>
                  <button
                    onClick={(e) => { e.preventDefault(); navigate("/wallet"); }}
                    className="rounded-xl bg-white/20 px-3 py-1.5 text-xs font-black backdrop-blur-sm hover:bg-white/30"
                  >
                    Top up
                  </button>
                </div>
              </div>
              {/* Progress bar */}
              <div className="relative mt-4">
                <div className="h-1.5 overflow-hidden rounded-full bg-white/20">
                  <motion.div
                    initial={reduced ? undefined : { width: 0 }}
                    animate={{ width: `${Math.min((rewardPoints / 2000) * 100, 100)}%` }}
                    transition={{ duration: 0.8, delay: 0.3, ease: "easeOut" }}
                    className="h-full rounded-full bg-white"
                  />
                </div>
                <p className="mt-1.5 text-[10px] font-bold text-white/50">
                  {Math.max(0, 2000 - rewardPoints)} pts to Diamond
                </p>
              </div>
            </div>
          </Link>
        </motion.div>

        {/* Today's deals */}
        {studentOffers.length > 0 && (
          <section>
            <div className="mb-3 flex items-center justify-between">
              <h2 className="font-heading text-base font-black">
                Today's deals <span className="text-base">🔥</span>
              </h2>
              <Link to="/restaurants" className="inline-flex items-center gap-1 text-sm font-bold text-primary">
                See all <ArrowRight size={13} />
              </Link>
            </div>
            <div className="scroll-snap-x">
              {studentOffers.map((offer) => (
                <div
                  key={offer.id}
                  onClick={() => navigate("/restaurants")}
                  className="w-72 shrink-0 cursor-pointer overflow-hidden rounded-2xl shadow-card transition-shadow hover:shadow-lift"
                  style={{ background: "#101010", border: "1px solid rgba(255,255,255,0.06)" }}
                >
                  <div className="flex items-center gap-3 p-3">
                    <img
                      src={offer.image}
                      alt={offer.title}
                      className="h-20 w-24 shrink-0 rounded-xl object-cover"
                      loading="lazy"
                    />
                    <div className="min-w-0">
                      <span className="inline-block rounded-full bg-primary px-2 py-0.5 text-[10px] font-black text-white">
                        {offer.discountPercent}% OFF
                      </span>
                      <p className="mt-1 font-heading text-sm font-black leading-tight">{offer.title}</p>
                      <p className="mt-0.5 text-xs text-muted-foreground line-clamp-1">{offer.restaurantName}</p>
                      <button className="mt-2 rounded-xl bg-primary px-3 py-1.5 text-xs font-black text-white shadow-lift transition-transform active:scale-95">
                        View deal
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* Trending now */}
        <section>
          <div className="mb-3 flex items-center gap-2">
            <h2 className="font-heading text-base font-black">
              Trending now <span className="text-base">✨</span>
            </h2>
          </div>
          <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
            {popularMeals.slice(0, 4).map((item, i) => (
              <motion.div
                key={item.id}
                initial={reduced ? undefined : { opacity: 0, y: 16 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.06 }}
              >
                <TrendingCard item={item} onAdd={() => navigate(`/restaurants/${item.restaurantId}`)} />
              </motion.div>
            ))}
          </div>
        </section>

        {/* Continue previous order */}
        {lastOrder && (
